#!/usr/bin/env python3
"""Create a local listing review from saved evidence; no network or publishing."""
import argparse
from datetime import date
from html import escape
import json
import os
from pathlib import Path
import sqlite3
from urllib.parse import quote

from play_listing import ROOT, summary, grouped, selected


def review(directory, database, output, start, end):
    directory,output=directory.resolve(),output.resolve()
    copy=json.loads((directory/'copy.json').read_text())
    manifest=json.loads((directory/'manifest.json').read_text())
    conn=sqlite3.connect(f'file:{database}?mode=ro',uri=True);conn.row_factory=sqlite3.Row
    stats=summary(conn,start,end)
    totals=grouped(selected(conn,'store_performance','traffic_source',start,end))['all reported segments']
    baseline=conn.execute('SELECT * FROM listing_locales WHERE version_id=(SELECT id FROM listing_versions WHERE version=1) AND locale=?',('en-US',)).fetchone()
    count=conn.execute('SELECT count(*) FROM report_objects').fetchone()[0]
    def href(path):return quote(os.path.relpath(path,output.parent))
    def fmt(value):return f'{value:,.0f}' if value is not None else 'Unavailable'
    def pct(value):return f'{value:.1%}' if value is not None else 'Unavailable'
    def table(rows):
        body=''.join(f'<tr><td>{escape(label)}</td><td>{fmt(s["visitors"])}</td><td>{fmt(s["acquisitions"])}</td><td>{pct(s["acquisition_conversion_rate"])}</td></tr>' for label,s in rows)
        return '<div class="table-scroll"><table><thead><tr><th>Reported segment</th><th>Visitors</th><th>Acquisitions</th><th>Acq. / visitors</th></tr></thead><tbody>'+body+'</tbody></table></div>'
    galleries=[]
    for kind,label in [('phoneScreenshots','Phone · 1080×1920'),('sevenInchScreenshots','7-inch class · 1080×1920'),('tenInchScreenshots','10-inch class · 1920×1080')]:
        figures=''.join(f'<a href="{href(directory/a["path"])}"><img loading="lazy" src="{href(directory/a["path"])}" alt="{escape(a["alt_text"],quote=True)}"></a>' for a in manifest['assets'] if a['kind']==kind)
        galleries.append(f'<details {"open" if kind=="phoneScreenshots" else ""}><summary>{label}</summary><div class="gallery {"wide" if kind=="tenInchScreenshots" else ""}">{figures}</div></details>')
    bars=''.join(f'<div class="bar-row"><span>{escape(label)}</span><div class="track"><div style="width:{s["acquisition_conversion_rate"]*100:.2f}%"></div></div><strong>{pct(s["acquisition_conversion_rate"])}</strong></div>' for label,s in stats['traffic_sources'].items())
    latest={}
    for row in stats['freshness']:
        latest[row['kind']]=max(latest.get(row['kind'],''),row['latest_date'])
    proposed=escape(copy['fullDescription']).replace('&lt;b&gt;','<b>').replace('&lt;/b&gt;','</b>').replace('\n','<br>')
    html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Comfer · Listing v002 review</title>
<style>@font-face{font-family:Inter;src:url(FONT)}*{box-sizing:border-box}body{margin:0;background:#f5f3ec;color:#173a35;font:15px/1.6 Inter,Arial,sans-serif}main{max-width:1240px;margin:auto;padding:45px 30px}a{color:#1b6558}header{display:flex;justify-content:space-between;align-items:start;gap:30px}.eyebrow{font-size:12px;letter-spacing:.13em;text-transform:uppercase}h1{font-size:48px;line-height:1.08;font-weight:570;margin:14px 0 20px;letter-spacing:-.04em}h2{font-size:27px;letter-spacing:-.025em;margin:0 0 18px;font-weight:580}h3{font-size:17px;margin:25px 0 10px}.pill{padding:7px 14px;border:1px solid #93b9aa;border-radius:30px;white-space:nowrap}.muted,small{color:#597069}.notice{margin:30px 0;padding:21px 25px;background:#f1e0cd;border-left:4px solid #9a633e;border-radius:0 12px 12px 0}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin:28px 0 15px}.metric{background:#d8e8dd;border-radius:16px;padding:23px}.number{display:block;font-size:36px;font-weight:580;letter-spacing:-.04em}section{padding:32px 0;border-top:1px solid #ccd4c9;margin-top:30px}.columns{display:grid;grid-template-columns:1fr 1fr;gap:34px}.card{background:#fff;border:1px solid #e1e4db;border-radius:16px;padding:25px}.title-copy{font-size:29px;font-weight:570;letter-spacing:-.025em}.feature{display:block;width:100%;max-width:1024px;margin:auto;border-radius:16px}.gallery{display:grid;grid-template-columns:repeat(5,minmax(140px,1fr));gap:14px;overflow:auto;padding:18px 0}.gallery img{display:block;width:100%;border-radius:10px}.gallery.wide{grid-template-columns:repeat(3,minmax(240px,1fr))}details{margin:18px 0}summary{cursor:pointer;font-weight:550}pre,code{font-family:ui-monospace,SFMono-Regular,monospace;font-size:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#e8eee7;border-radius:9px;padding:16px}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:11px 9px;border-bottom:1px solid #dce3d9;text-align:right}th:first-child,td:first-child{text-align:left}th{color:#587069;font-weight:520}.bar-row{display:grid;grid-template-columns:155px 1fr 60px;gap:15px;align-items:center;margin:13px 0;font-size:13px}.track{background:#e0e7dc;border-radius:8px;height:15px;overflow:hidden}.track div{background:#2d6c5a;height:100%}.links{display:flex;flex-wrap:wrap;gap:12px}.links a{display:inline-block;background:#173e35;color:white;padding:10px 17px;border-radius:8px;text-decoration:none}ul{padding-left:21px}li{margin:8px 0}@media(max-width:760px){main{padding:25px 17px}header,.columns{display:block}h1{font-size:38px}.pill{display:inline-block}.metrics{grid-template-columns:1fr}.number{font-size:32px}.bar-row{grid-template-columns:125px 1fr 50px}.columns>.card{margin-bottom:18px}.gallery{grid-template-columns:repeat(5,180px)}}</style>
<main><header><div><div class="eyebrow">Comfer / Google Play listing</div><h1>Comfort in<br>everyday use.</h1><p class="muted">Version 002 · English (en-US) · Captured from release-58 source</p></div><span class="pill">Prepared locally · publication pending</span></header>
<div class="notice"><strong>Publication hold: reconcile the existing privacy disclosures.</strong><br>The public Data safety section says no data is collected, and the linked policy says there is no analytics. The release manifest includes Firebase initialization and Analytics/Crashlytics registrars. The candidate replaces unsupported privacy and performance claims. Review the SDK data practices and correct the connected disclosures before publication. No activation date is recorded.</div>
<div class="links"><a href="BUNDLE">Download v002 artwork + sources</a><a href="MANIFEST">Copy and asset manifest</a><a href="DATABASE">Versioned baseline database</a></div>
<section><div class="eyebrow">Latest complete 28-day acquisition context</div><h2>PERIOD</h2><div class="metrics"><div class="metric"><span class="number">VISITORS</span>Reported visitor observations</div><div class="metric"><span class="number">ACQUISITIONS</span>Successful listing acquisitions</div><div class="metric"><span class="number">CONVERSION</span>Matched acquisition conversion</div></div><small>Pacific Time; daily per-segment totals, not period-unique people. Legacy acquisition exports differ from 2026 Console install-click/CTR metrics. Historical listing exposure is unverified, so this is pre-change context.</small><div class="columns"><div><h3>Traffic sources</h3>BARS<p class="muted">The Explore gap makes clarity for unfamiliar users a useful hypothesis. It does not establish that the old creative caused the gap.</p></div><div><h3>Observed Google Play Search terms</h3>KEYWORDS<small>Search only. Suppressed terms remain Other. These counts do not measure the store's total keyword search volume.</small></div></div><details><summary>Country breakdown · a separate report axis</summary>COUNTRIES</details></section>
<section><h2>The proposed copy</h2><div class="columns"><div class="card"><div class="eyebrow">Title · TITLELEN / 30</div><div class="title-copy">TITLE</div><h3>Short description · SHORTLEN / 80</h3><p>SHORT</p><p class="muted">Keep Comfer and Comfort recognition. Explain the actual swipe, search and workspace experience. Generic minimalist/gesture phrases remain relevance hypotheses; no Play-wide volume is claimed.</p></div><div class="card"><div class="eyebrow">Full description · FULLLEN / 4,000</div><div>FULL</div></div></div><details><summary>Observed v001 copy, archived unchanged</summary><pre>BASELINE</pre></details></section>
<section><h2>Feature graphic</h2><img class="feature" src="FEATURE" alt="Comfer feature graphic: Make yourself at home"><p class="muted">1024×500 opaque RGB. Essential copy stays central. The app view is a documented detail crop of the genuine home capture.</p><h2>Screenshot sequence</h2>GALLERIES<p class="muted">5 phone + 5 portrait tablet + 5 landscape tablet images. Original captures, crop coordinates, source APK hash, alt text, editable SVGs and the Inter font/license are included. Tablet images are native tablet-sized emulator layouts without promotional overlays. English/LTR only; no physical tablet verification or RTL media localization is claimed.</p></section>
<section><h2>What was fetched</h2><table><thead><tr><th>Evidence</th><th>Availability / freshness</th></tr></thead><tbody><tr><td>Main listing</td><td>en-US title, short/full description, video URL, icon, feature graphic, all 24 existing screenshots; observed Oct 22</td></tr><tr><td>Release tracks</td><td>Production version code 58; temporary Publisher edit deleted without commit</td></tr><tr><td>Acquisition reports</td><td>Search terms, visitors, acquisitions, conversion, traffic/UTM and country axes through ACQDATE</td></tr><tr><td>Install / rating reports</td><td>Overview, country, language and app-version axes through INSTALLDATE</td></tr><tr><td>Reviews / quality context</td><td>Written/rating-only reviews through REVIEWDATE; crash/ANR counts through CRASHDATE</td></tr><tr><td>Archive</td><td>REPORTCOUNT immutable report generations; raw CSVs and image bytes stored in SQLite</td></tr><tr><td>Public page</td><td>Category, 1M+ download bucket, Everyone content rating, localized rating signal and linked privacy disclosures</td></tr><tr><td>Not collected</td><td>Current Console install-click CTR, peer benchmarks, custom-listing/experiment exposure and retained-install cohorts</td></tr></tbody></table><p class="muted">Country and install-language reports are separate margins; they cannot establish a country-by-language funnel. Public ratings vary by storefront and differ from exported cumulative averages.</p><h3>Free keyword sources</h3><p>The shortlist uses actual app search terms from the authorized Google Play exports. <a href="https://appdrift.co/tools/keyword-suggestion">AppDrift</a> and <a href="https://keywordtool.io/play-store">Keyword Tool</a> advertise free Play suggestions; paid volumes and illustrative samples were not used. The legacy direct Play-autocomplete endpoint failed and is recorded as unavailable, not zero demand. <a href="https://support.google.com/trends/answer/4365533?hl=en">Google Trends</a> is a web-interest signal, not Play volume. Comparable public listings informed vocabulary only.</p></section>
<section><h2>How the next evaluation works</h2><ol><li>Reconcile the connected disclosures and review this candidate. Publishing and any Console experiment remain separate actions.</li><li>After verified publication, record the actual activation timestamp and exposure evidence. Preparing a version never starts its performance clock.</li><li>Refresh reports, then compare equal complete 28-day windows around activation, excluding the transition day. The command stays inconclusive when dates are missing or another listing version overlaps.</li><li>Review Explore and Search separately, preserve branded query acquisition, and consider releases, campaigns, quality and localization. A whole-listing before/after comparison cannot isolate the cause of a change.</li><li>For the next isolated test, use one asset and one variant with Console's current sample-size estimate and target metric. Arabic/French localization is a follow-up opportunity from install-language evidence.</li></ol><pre>venv/bin/python scripts/play_listing.py sync --days 90\nvenv/bin/python scripts/play_listing.py compare --version 2 --days 28\n\n# Only after verified publication; supply its actual timestamp/evidence:\nvenv/bin/python scripts/play_listing.py activate --version 2 \\\n  --effective-at ACTUAL_TIME_WITH_TIMEZONE --evidence PUBLICATION_EVIDENCE\n\nvenv/bin/python scripts/render_play_listing.py --directory store-listing/v002</pre><p class="muted">No live experiment or recurring schedule was started. The existing video URL and icon are retained; no video was generated.</p></section>
<section><h2>Validation and sources</h2><p>16 assets fully decoded and passed the local Google Play image/copy contract. Capture instrumentation passed at all three viewports. Database history, new generations, missing metrics, time zones, exposure and observation mapping have focused regressions. Local checks do not establish Google review approval or conversion uplift.</p><ul><li><a href="https://support.google.com/googleplay/android-developer/answer/9866151?hl=en">Google Play preview-asset specifications</a></li><li><a href="https://support.google.com/googleplay/android-developer/answer/13393723?hl=en">Google Play listing practices</a></li><li><a href="https://support.google.com/googleplay/android-developer/answer/9859173?hl=en">Current performance metric definitions</a></li><li><a href="https://support.google.com/googleplay/android-developer/answer/12053285?hl=en">Store listing experiments</a></li><li><a href="https://comfer.jeerovan.com/privacy">Current linked privacy policy</a></li></ul><p class="muted">Research and collection: October 22, 2026. Detailed source identities, keyword evidence, limitations and validation receipts are in play_listing.db. Private performance evidence is kept out of Git.</p></section></main></html>'''
    values={'FONT':href(directory/'fonts/InterVariable.ttf'),'BUNDLE':href(directory.parent/'comfer-listing-v002.zip'),
            'MANIFEST':href(directory/'manifest.json'),'DATABASE':href(database),'FEATURE':href(directory/'upload/feature-graphic.png'),
            'PERIOD':f'{start:%B %d} – {(end-date.resolution):%B %d, %Y}',
            'VISITORS':fmt(totals['visitors']),'ACQUISITIONS':fmt(totals['acquisitions']),'CONVERSION':pct(totals['acquisition_conversion_rate']),
            'BARS':bars,'KEYWORDS':table(list(stats['search_terms_search_only'].items())[:6]),
            'COUNTRIES':table(list(stats['countries_separate_axis'].items())[:12]),
            'TITLELEN':str(len(copy['title'])),'SHORTLEN':str(len(copy['shortDescription'])),'FULLLEN':str(len(copy['fullDescription'])),
            'TITLE':escape(copy['title']),'SHORT':escape(copy['shortDescription']),'FULL':proposed,
            'BASELINE':escape(baseline['title']+'\n\n'+baseline['short_description']+'\n\n'+baseline['full_description']),
            'GALLERIES':''.join(galleries),'ACQDATE':latest['store_performance'],'INSTALLDATE':latest['installs'],
            'REVIEWDATE':latest['reviews'],'CRASHDATE':latest['crashes'],'REPORTCOUNT':str(count)}
    # Single regex substitution avoids interpreting replacement text as templates.
    import re
    html=re.sub(r'\b('+ '|'.join(sorted(values,key=len,reverse=True)) +r')\b',lambda m:values[m[0]],html)
    output.parent.mkdir(parents=True,exist_ok=True);output.write_text(html)
    print(output)
    conn.close()


if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--directory',type=Path,default=ROOT/'store-listing/v002')
    parser.add_argument('--database',type=Path,default=ROOT/'play_listing.db')
    parser.add_argument('--output',type=Path,default=ROOT/'store-listing/private/review.html')
    parser.add_argument('--start',type=date.fromisoformat,default=date(2026,9,18))
    parser.add_argument('--end',type=date.fromisoformat,default=date(2026,10,16))
    args=parser.parse_args();review(args.directory,args.database,args.output,args.start,args.end)
